def assign_neg_difficulty_quartiles(
    all_results: Dict[str, Dict[int, List[Dict]]],
    val_samples_cache: Dict[str, List[Dict]],
):
    """Compute text-overlap-based neg difficulty proxy and assign quartiles."""
    for strategy in list(all_results.keys()):
        for seed in list(all_results[strategy].keys()):
            results = all_results[strategy][seed]
            cache_key = f"{strategy}_s{seed}"
            samples = val_samples_cache.get(cache_key, [])
            sample_map = {s["query_id"]: s for s in samples}

            margins = []
            for r in results:
                s = sample_map.get(r["query_id"])
                if s is None:
                    margins.append(0.0)
                    continue
                q_toks = set(s.get("query_tokens", "")[:1000].split())
                p_toks = set(s.get("pos_tokens", "")[:1000].split())
                pos_overlap = len(q_toks & p_toks) / max(len(q_toks | p_toks), 1)
                max_neg_overlap = 0.0
                neg_cands = s.get("neg_candidates", [])[:7]
                cand_tokens = s.get("candidate_tokens", {})
                for neg_id in neg_cands:
                    neg_text = cand_tokens.get(neg_id, "")
                    if neg_text:
                        n_toks = set(neg_text[:1000].split())
                        ov = len(q_toks & n_toks) / max(len(q_toks | n_toks), 1)
                        max_neg_overlap = max(max_neg_overlap, ov)
                margin = pos_overlap - max_neg_overlap
                margins.append(margin)
                r["neg_difficulty_margin"] = margin

            if margins:
                arr = np.array(margins)
                q25, q50, q75 = np.percentile(arr, [25, 50, 75])
                for r, m in zip(results, margins):
                    if m <= q25:
                        r["neg_difficulty_bin"] = "Q4_hard"
                    elif m <= q50:
                        r["neg_difficulty_bin"] = "Q3"
                    elif m <= q75:
                        r["neg_difficulty_bin"] = "Q2"
                    else:
                        r["neg_difficulty_bin"] = "Q1_easy"


def group_by(results: List[Dict], key: str) -> Dict[str, List[Dict]]:
    groups: Dict[str, List[Dict]] = defaultdict(list)
    for r in results:
        groups[r[key]].append(r)
    return dict(groups)


