def run_pool_size_controlled_analysis(
    all_results: Dict[str, Dict[int, List[Dict]]],
    n_bootstrap: int = 1000,
) -> Dict:
    """Compare strategies within same pool_size bins to control for pool size confound.

    Rich-dataflow instances tend to have larger candidate pools, making R@1
    inherently lower. By matching on pool_size before comparing strategies,
    this isolates the true strategy effect from pool-size confounding.

    Args:
        all_results: {strategy: {seed: [result_dicts]}}
        n_bootstrap: bootstrap iterations for CI

    Returns:
        Dict with per-pool_size_bin per-strategy metrics, within-bin deltas,
        and aggregate weighted delta.
    """
    analysis = {}
    for pool_bin in POOL_SIZE_BINS:
        analysis[pool_bin] = {}
        for strategy in STRATEGIES:
            bin_results = []
            for seed, results in all_results.get(strategy, {}).items():
                for r in results:
                    if r.get("pool_size_bin") == pool_bin:
                        bin_results.append(r)

            metrics = compute_metrics(bin_results)
            ci_r1 = bootstrap_ci(bin_results, "R@1", n_bootstrap)
            ci_r5 = bootstrap_ci(bin_results, "R@5", n_bootstrap)
            ci_mrr = bootstrap_ci(bin_results, "MRR", n_bootstrap)
            analysis[pool_bin][strategy] = {
                "R@1": ci_r1[0],
                "R@1_ci": [ci_r1[1], ci_r1[2]],
                "R@5": ci_r5[0],
                "R@5_ci": [ci_r5[1], ci_r5[2]],
                "MRR": ci_mrr[0],
                "MRR_ci": [ci_mrr[1], ci_mrr[2]],
                "count": metrics["count"],
            }

        # Within-bin deltas (controlled for pool size)
        rand_m = analysis[pool_bin].get("random", {})
        for other in ["embedding_distance", "dataflow_aware"]:
            other_m = analysis[pool_bin].get(other, {})
            delta_key = f"{other}_vs_random"
            if rand_m and other_m:
                for metric in ["R@1", "R@5", "MRR"]:
                    rv = rand_m.get(metric, 0)
                    ov = other_m.get(metric, 0)
                    analysis[pool_bin].setdefault(delta_key, {})[f"{metric}_delta"] = ov - rv
                    analysis[pool_bin][delta_key][f"{metric}_rel_pct"] = (
                        (ov - rv) / rv * 100 if rv > 0 else 0.0
                    )

    # Aggregate controlled delta: count-weighted average of within-bin deltas
    for other in ["embedding_distance", "dataflow_aware"]:
        delta_key = f"{other}_vs_random"
        total_n = 0
        weighted_delta = 0.0
        for pool_bin in POOL_SIZE_BINS:
            n = analysis[pool_bin].get(other, {}).get("count", 0)
            d = analysis[pool_bin].get(delta_key, {}).get("R@1_delta", 0)
            weighted_delta += d * n
            total_n += n
        analysis[f"aggregate_{delta_key}"] = {
            "R@1_weighted_delta": weighted_delta / total_n if total_n > 0 else 0.0,
            "total_n": total_n,
        }

    return analysis


